import{_ as i,H as o,f as a,i as e}from"./chunks/framework.Cvt1eIE0.js";const g=JSON.parse('{"title":"Design: Claude Code 中文渐进式教程","description":"","frontmatter":{},"headers":[],"relativePath":"yaojianfeng-master-design-20260524-220217.md","filePath":"yaojianfeng-master-design-20260524-220217.md"}'),t={name:"yaojianfeng-master-design-20260524-220217.md"};function r(s,l,n,u,p,d){return o(),a("div",null,[...l[0]||(l[0]=[e(`<h1 id="design-claude-code-中文渐进式教程" tabindex="-1">Design: Claude Code 中文渐进式教程 <a class="header-anchor" href="#design-claude-code-中文渐进式教程" aria-label="Permalink to &quot;Design: Claude Code 中文渐进式教程&quot;">​</a></h1><p>Generated by /office-hours on 2026-05-24 Branch: master Status: APPROVED Mode: Builder</p><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>创建一个系统的、从简到难的中文 Claude Code 教程，面向完全零基础的用户。核心解决现有教程&quot;缺乏系统性&quot;的问题，让用户学完后具备继续探索高级用法的基础。</p><h2 id="what-makes-this-cool" tabindex="-1">What Makes This Cool <a class="header-anchor" href="#what-makes-this-cool" aria-label="Permalink to &quot;What Makes This Cool&quot;">​</a></h2><p>让 AI 编程工具的入门门槛降到最低。不是堆砌功能清单，而是构建一条<strong>平滑的学习曲线</strong>，让每个初学者都能从头走到继续探索的那一步。</p><h2 id="target-user-narrowest-wedge" tabindex="-1">Target User &amp; Narrowest Wedge <a class="header-anchor" href="#target-user-narrowest-wedge" aria-label="Permalink to &quot;Target User &amp; Narrowest Wedge&quot;">​</a></h2><p><strong>目标用户：</strong> 高校学生、教师、刚入行的开发者——用过代码但没用过 AI 辅助编程工具的人</p><p><strong>最小可行内容（MVP）：</strong></p><ol><li>环境安装配置</li><li>API Key 获取与安全使用</li><li>基础对话流程（读文件、改代码、解释代码）</li><li>日常工作辅助场景（调试、代码审查）</li></ol><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li>全程中文</li><li>面向零基础，但需要有一定的编程基础（至少写过代码）</li><li>可扩展：模块化设计，方便后续添加内容</li><li>静态网站，便于托管和访问</li></ul><h2 id="approaches-considered" tabindex="-1">Approaches Considered <a class="header-anchor" href="#approaches-considered" aria-label="Permalink to &quot;Approaches Considered&quot;">​</a></h2><h3 id="approach-a-mvp-先跑-推荐" tabindex="-1">Approach A: MVP 先跑（推荐） <a class="header-anchor" href="#approach-a-mvp-先跑-推荐" aria-label="Permalink to &quot;Approach A: MVP 先跑（推荐）&quot;">​</a></h3><ul><li>5-7 个核心模块，每个模块 2-3 篇文章</li><li>VitePress + GitHub Pages</li><li>2-4 周上线第一版</li><li>渐进扩展</li></ul><h3 id="approach-b-完整知识库" tabindex="-1">Approach B: 完整知识库 <a class="header-anchor" href="#approach-b-完整知识库" aria-label="Permalink to &quot;Approach B: 完整知识库&quot;">​</a></h3><ul><li>10+ 模块，覆盖所有内容</li><li>Docusaurus + i18n</li><li>8-12 周完成初版</li></ul><h3 id="approach-c-交互式教程" tabindex="-1">Approach C: 交互式教程 <a class="header-anchor" href="#approach-c-交互式教程" aria-label="Permalink to &quot;Approach C: 交互式教程&quot;">​</a></h3><ul><li>文档 + 可运行练习题</li><li>VitePress + GitHub Codespaces</li><li>4-6 周核心练习</li></ul><h2 id="recommended-approach" tabindex="-1">Recommended Approach <a class="header-anchor" href="#recommended-approach" aria-label="Permalink to &quot;Recommended Approach&quot;">​</a></h2><p><strong>方案 A（选择）：MVP 先跑</strong></p><p>原因：</p><ol><li>快速验证——2-4 周能看到实际效果</li><li>符合&quot;平滑曲线&quot;的设计理念——先给最核心的内容</li><li>降低维护压力——先上线，再迭代</li><li>渐进扩展性——模块化设计确保后续添加不破坏结构</li></ol><h2 id="content-structure-mvp-模块" tabindex="-1">Content Structure（MVP 模块） <a class="header-anchor" href="#content-structure-mvp-模块" aria-label="Permalink to &quot;Content Structure（MVP 模块）&quot;">​</a></h2><p>每个章节包含：</p><ul><li><strong>学习目标</strong>：学完这章能做什么</li><li><strong>前置知识</strong>：需要什么基础（几乎都是&quot;会打字就行&quot;）</li><li><strong>操作步骤</strong>：傻瓜式截图+命令</li><li><strong>常见问题</strong>：FAQ 提前预判</li><li><strong>练习题</strong>：学完马上练</li></ul><hr><h3 id="第一章-claude-code-是什么-10-分钟" tabindex="-1">第一章：Claude Code 是什么（10 分钟） <a class="header-anchor" href="#第一章-claude-code-是什么-10-分钟" aria-label="Permalink to &quot;第一章：Claude Code 是什么（10 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 理解 Claude Code 能做什么，不能做什么</p><p><strong>内容大纲：</strong></p><ul><li>Claude Code 是命令行工具，不是网页聊天</li><li>它能：读代码、写代码、改代码、解释代码</li><li>它不能：替你运行代码（需要你确认）</li><li>和 ChatGPT / Copilot 的区别是什么</li></ul><p><strong>前置知识：</strong> 无</p><p><strong>操作步骤：</strong> 无（纯概念）</p><p><strong>常见问题：</strong></p><ul><li>Q: Claude Code 要钱吗？A: 有免费额度，API Key 才收费</li><li>Q: 不会命令行能学吗？A: 教程会从零教</li></ul><hr><h3 id="第二章-安装-claude-code-15-20-分钟" tabindex="-1">第二章：安装 Claude Code（15-20 分钟） <a class="header-anchor" href="#第二章-安装-claude-code-15-20-分钟" aria-label="Permalink to &quot;第二章：安装 Claude Code（15-20 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 在自己电脑上成功安装 Claude Code</p><p><strong>内容大纲：</strong></p><ul><li>什么是终端/命令行</li><li>Windows 用户：安装 Windows Terminal + Claude Code</li><li>Mac 用户：使用终端 + Claude Code</li><li>Linux 用户：直接安装</li><li>验证安装成功：<code>claude --version</code></li></ul><p><strong>前置知识：</strong> 会开关电脑、会打字</p><p><strong>操作步骤（Windows 为例）：</strong></p><ol><li>下载 Claude Code 安装包（官网链接+百度网盘备链）</li><li>双击安装，一路下一步</li><li>打开 PowerShell 或 Windows Terminal</li><li>输入 <code>claude --version</code>，看到版本号即成功</li><li>截图确认</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: 提示&quot;找不到命令&quot;？A: 重启终端或重新安装</li><li>Q: 杀毒软件报警？A: 信任该软件，或暂时关闭杀毒</li></ul><p><strong>练习题：</strong> 在终端输入 <code>claude --version</code> 并截图</p><hr><h3 id="第三章-获取和配置-api-key-20-分钟" tabindex="-1">第三章：获取和配置 API Key（20 分钟） <a class="header-anchor" href="#第三章-获取和配置-api-key-20-分钟" aria-label="Permalink to &quot;第三章：获取和配置 API Key（20 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 拿到 Anthropic 官方的 API Key，并配置到 Claude Code</p><p><strong>前置知识：</strong> 会注册网站账号、有信用卡（可选）</p><p><strong>内容大纲：</strong></p><ul><li>什么是 API Key，为什么需要它</li><li>注册 Anthropic 账号的步骤（截图版）</li><li>创建 API Key 的位置</li><li>如何安全保管 API Key（不要分享、不要提交到 GitHub）</li><li>配置到 Claude Code：<code>claude --local</code></li><li>验证：输入 <code>claude</code> 看到对话界面</li></ul><p><strong>操作步骤：</strong></p><ol><li>打开 anthropic.com官网</li><li>点击 Sign Up 注册（可用 Google 账号）</li><li>登录后进入 Console</li><li>点击 API Keys → Create Key</li><li>复制 Key（只会显示一次！）</li><li>打开终端，输入 <code>claude</code> 按提示粘贴 Key</li><li>看到 <code>You can now start chatting!</code> 即成功</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: API Key 要钱吗？A: 有免费额度，初期够用</li><li>Q: Key 泄露了怎么办？A: 立刻在官网删除，重新生成</li><li>Q: 看不到 Create Key 按钮？A: 可能账号没激活，检查邮箱</li></ul><p><strong>练习题：</strong> 成功在 Claude Code 里问&quot;你好&quot;并收到回复</p><hr><h3 id="第四章-首次对话-hello-world-15-分钟" tabindex="-1">第四章：首次对话 - Hello World（15 分钟） <a class="header-anchor" href="#第四章-首次对话-hello-world-15-分钟" aria-label="Permalink to &quot;第四章：首次对话 - Hello World（15 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 学会和 Claude Code 对话的基本方式</p><p><strong>前置知识：</strong> 完成前三章</p><p><strong>内容大纲：</strong></p><ul><li>Claude Code 的两种模式：对话模式 / 单命令模式</li><li>如何退出：输入 <code>exit</code> 或按 <code>Ctrl+C</code></li><li>怎么问问题效果最好</li><li>第一次实战：让 Claude 解释一个简单文件</li></ul><p><strong>操作步骤：</strong></p><ol><li>打开终端，输入 <code>claude</code> 进入对话</li><li>输入&quot;你好&quot;</li><li>创建一个测试文件 <code>test.py</code>：写入 <code>print(&quot;Hello World&quot;)</code></li><li>问 Claude：&quot;帮我解释这个文件做了什么&quot;</li><li>观察 Claude 的回答格式</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: Claude 回答很慢？A: 正在生成，稍等即可</li><li>Q: 回答被截断了？A: 输入&quot;继续&quot;让它说完</li><li>Q: 答非所问？A: 换个问法，越具体越好</li></ul><p><strong>练习题：</strong> 让 Claude 帮你写一个&quot;计算两个数之和&quot;的 Python 程序</p><hr><h3 id="第五章-读懂代码库-20-分钟" tabindex="-1">第五章：读懂代码库（20 分钟） <a class="header-anchor" href="#第五章-读懂代码库-20-分钟" aria-label="Permalink to &quot;第五章：读懂代码库（20 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 学会让 Claude 分析和理解现有代码</p><p><strong>前置知识：</strong> 知道什么是代码文件（.py, .js 等）</p><p><strong>内容大纲：</strong></p><ul><li>为什么让 AI 读代码比你自己读更快</li><li>告诉 Claude 读哪个文件的语法</li><li>读懂整个项目的结构</li><li>案例：分析一个开源项目</li></ul><p><strong>操作步骤：</strong></p><ol><li>进入项目目录：<code>cd 你的项目路径</code></li><li>启动 Claude：<code>claude</code></li><li>问：&quot;请分析这个项目的结构&quot;</li><li>问：&quot;这个 main.py 的主要功能是什么&quot;</li><li>问：&quot;帮我理解 utils.py 里的 helper 函数&quot;</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: Claude 读错了？A: 确认你在正确的目录下</li><li>Q: 大项目分析很慢？A: 先指定具体文件，不要一次性分析整个项目</li></ul><p><strong>练习题：</strong> 把你的某个旧项目扔给 Claude，让它帮你写 README</p><hr><h3 id="第六章-编辑和创建代码-25-分钟" tabindex="-1">第六章：编辑和创建代码（25 分钟） <a class="header-anchor" href="#第六章-编辑和创建代码-25-分钟" aria-label="Permalink to &quot;第六章：编辑和创建代码（25 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 学会让 Claude 直接帮你写代码、修改代码</p><p><strong>前置知识：</strong> 知道代码文件存在哪</p><p><strong>内容大纲：</strong></p><ul><li>两种编辑方式：直接生成代码 / 渐进式修改</li><li>让 Claude 创建新文件</li><li>让 Claude 修改现有文件（Edit 模式）</li><li>如何审查 Claude 生成的代码（一定要看！）</li><li>怎么拒绝/要求重写</li></ul><p><strong>操作步骤：</strong></p><ol><li>创建新文件：问&quot;帮我创建一个 sum.py，实现加法函数&quot;</li><li>修改现有文件：问&quot;把这个函数的返回值从 int 改成 float&quot;</li><li>使用 /edit 命令进入编辑模式</li><li>Claude 生成修改后，会询问你确认 Apply（接受）或拒绝</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: Claude 写的代码报错？A: 把错误信息粘贴给它，让它修复</li><li>Q: 不想用 Claude 写的？A: 直接说&quot;不要这个方案，换一个&quot;</li><li>Q: 怎么只接受部分修改？A: 可以手动微调，Claude 不会介意</li></ul><p><strong>练习题：</strong></p><ol><li>让 Claude 帮你写一个&quot;学生成绩管理&quot;的程序</li><li>让它添加&quot;添加学生&quot;和&quot;查看成绩&quot;功能</li></ol><hr><h3 id="第七章-多轮对话技巧-20-分钟" tabindex="-1">第七章：多轮对话技巧（20 分钟） <a class="header-anchor" href="#第七章-多轮对话技巧-20-分钟" aria-label="Permalink to &quot;第七章：多轮对话技巧（20 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 学会通过多轮对话完善代码</p><p><strong>前置知识：</strong> 会基本的对话操作</p><p><strong>内容大纲：</strong></p><ul><li>为什么多轮对话比一次性描述更有效</li><li>场景演练：一步步完善一个功能</li><li>怎么利用上下文（Claude 记得对话历史）</li><li>什么时候该开新对话</li></ul><p><strong>操作步骤：</strong></p><ol><li>第一轮：让 Claude 写一个&quot;待办事项&quot;的基本结构</li><li>第二轮：添加&quot;标记完成&quot;功能</li><li>第三轮：添加&quot;保存到文件&quot;功能</li><li>观察 Claude 如何在前面的基础上继续开发</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: Claude 忘了之前的对话？A: 超过一定长度可能遗忘，可开新对话并简要描述背景</li><li>Q: 对话乱了？A: 输入 /clear 清空重来</li></ul><p><strong>练习题：</strong> 用多轮对话方式，让 Claude 帮你做一个&quot;记账本&quot;程序</p><hr><h3 id="第八章-调试和错误处理-25-分钟" tabindex="-1">第八章：调试和错误处理（25 分钟） <a class="header-anchor" href="#第八章-调试和错误处理-25-分钟" aria-label="Permalink to &quot;第八章：调试和错误处理（25 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 学会让 Claude 帮你找 bug 和修复错误</p><p><strong>前置知识：</strong> 写过能运行的代码</p><p><strong>内容大纲：</strong></p><ul><li>把错误信息粘贴给 Claude</li><li>让 Claude 添加日志定位问题</li><li>常见 Python/JS 错误讲解</li><li>调试心态：AI 辅助不是万能的</li></ul><p><strong>操作步骤：</strong></p><ol><li>你的代码报错，把完整错误信息复制</li><li>粘贴给 Claude：&quot;帮我看看这个错误&quot;</li><li>Claude 解释原因后，让它修复</li><li>运行确认修复成功</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: 同样的错误修完又出现？A: 可能需要从根本上重构</li><li>Q: Claude 修错了？A: 用 /undo 撤销，或手动回滚</li></ul><p><strong>练习题：</strong></p><ol><li>故意写一个有 bug 的代码</li><li>让 Claude 帮你找出来并修复</li></ol><hr><h3 id="第九章-代码审查和优化-20-分钟" tabindex="-1">第九章：代码审查和优化（20 分钟） <a class="header-anchor" href="#第九章-代码审查和优化-20-分钟" aria-label="Permalink to &quot;第九章：代码审查和优化（20 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 学会让 Claude 做代码审查</p><p><strong>前置知识：</strong> 有代码仓库</p><p><strong>内容大纲：</strong></p><ul><li>代码审查是什么，为什么重要</li><li>让 Claude 审查自己的代码</li><li>常见代码问题：命名、重复代码、安全隐患</li><li>优化建议：性能、可读性、架构</li></ul><p><strong>操作步骤：</strong></p><ol><li>问 Claude：&quot;请审查这个文件的代码问题&quot;</li><li>问：&quot;有哪些地方可以优化？&quot;</li><li>逐个讨论每个问题</li><li>让 Claude 帮你优化</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: Claude 说的对不对？A: 你是最终决策者，保持批判思维</li><li>Q: 优化建议太多了？A: 优先处理高风险问题</li></ul><p><strong>练习题：</strong> 找一段旧代码让 Claude 审查，并实施它的优化建议</p><hr><h3 id="第十章-git-操作辅助-20-分钟" tabindex="-1">第十章：Git 操作辅助（20 分钟） <a class="header-anchor" href="#第十章-git-操作辅助-20-分钟" aria-label="Permalink to &quot;第十章：Git 操作辅助（20 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 学会让 Claude 辅助 Git 操作</p><p><strong>前置知识：</strong> 知道 Git 是什么（不知道也没关系，会抄命令就行）</p><p><strong>内容大纲：</strong></p><ul><li>Git 基础：commit / push / pull / branch</li><li>让 Claude 帮你写 commit message</li><li>让 Claude 帮你处理 merge 冲突</li><li>PR 描述怎么写</li></ul><p><strong>操作步骤：</strong></p><ol><li>修改代码后，问 Claude：&quot;帮我看看这些修改&quot;</li><li>问：&quot;帮我写一个 commit message&quot;</li><li>如果有冲突，把冲突信息粘贴给 Claude</li><li>问：&quot;这个冲突怎么解决？&quot;</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: merge 冲突太复杂？A: 让 Claude 先解释冲突是什么，再决定怎么合并</li><li>Q: 误操作了？A: <code>git reflog</code> 可以找回之前的版本</li></ul><p><strong>练习题：</strong></p><ol><li>修改文件，用 Claude 帮你写 commit message</li><li>制造一个 merge 冲突，让 Claude 帮你分析</li></ol><hr><h3 id="第十一章-claude-md-给-ai-写说明书-15-分钟" tabindex="-1">第十一章：CLAUDE.md - 给 AI 写说明书（15 分钟） <a class="header-anchor" href="#第十一章-claude-md-给-ai-写说明书-15-分钟" aria-label="Permalink to &quot;第十一章：CLAUDE.md - 给 AI 写说明书（15 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 学会创建项目规范文件，让 AI 更懂你的项目</p><p><strong>前置知识：</strong> 有代码项目</p><p><strong>内容大纲：</strong></p><ul><li>什么是 CLAUDE.md</li><li>什么时候需要 CLAUDE.md</li><li>怎么写项目说明（语言、架构、约定）</li><li>实际案例讲解</li></ul><p><strong>操作步骤：</strong></p><ol><li>在项目根目录创建 <code>CLAUDE.md</code></li><li>写入项目名称、描述、技术栈</li><li>写入代码规范（如：使用中文注释）</li><li>写入常用命令</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: 一定要写吗？A: 不是，但写了 Claude 表现更好</li><li>Q: 写在哪里？A: 项目根目录</li></ul><p><strong>练习题：</strong> 给你现有项目创建一个 CLAUDE.md</p><hr><h3 id="第十二章-日常工作流实战-30-分钟" tabindex="-1">第十二章：日常工作流实战（30 分钟） <a class="header-anchor" href="#第十二章-日常工作流实战-30-分钟" aria-label="Permalink to &quot;第十二章：日常工作流实战（30 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 整合前面所学，体验完整工作流</p><p><strong>前置知识：</strong> 学完前十一章</p><p><strong>内容大纲：</strong></p><ul><li>场景一：接需求 → 写代码 → 自测 → 提交 PR</li><li>场景二：接手旧项目 → 理解代码 → 修 bug → 提交</li><li>场景三：代码审查 → 提出修改 → 优化 → 完成</li></ul><p><strong>操作步骤：</strong></p><ol><li>选择一个简单需求</li><li>和 Claude 一起完成全流程</li><li>记录遇到的问题和解决方法</li></ol><p><strong>常见问题：</strong></p><ul><li>Q: 遇到不会的步骤？A: 回到对应章节复习</li></ul><p><strong>练习题：</strong> 从 GitHub 找一个简单的开源项目，完整走一遍修改流程</p><hr><h3 id="第十三章-继续学习之路-10-分钟" tabindex="-1">第十三章：继续学习之路（10 分钟） <a class="header-anchor" href="#第十三章-继续学习之路-10-分钟" aria-label="Permalink to &quot;第十三章：继续学习之路（10 分钟）&quot;">​</a></h3><p><strong>学习目标：</strong> 知道接下来学什么</p><p><strong>前置知识：</strong> 学完前十二章</p><p><strong>内容大纲：</strong></p><ul><li>官方文档阅读指南</li><li>进阶话题：MCP、Agent 模式、API 集成</li><li>推荐学习路径</li><li>资源链接</li></ul><p><strong>常见问题：</strong></p><ul><li>Q: 忘记了某章内容？A: 随时回来查</li><li>Q: 想学更深入的？A: 查看官方文档</li></ul><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><ul><li><strong>框架：</strong> VitePress</li><li><strong>托管：</strong> GitHub Pages</li><li><strong>CI/CD：</strong> GitHub Actions（自动部署）</li><li><strong>域名：</strong> 可选（初期用 GitHub Pages 免费托管）</li></ul><h2 id="project-structure-mvp" tabindex="-1">Project Structure（MVP） <a class="header-anchor" href="#project-structure-mvp" aria-label="Permalink to &quot;Project Structure（MVP）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claudecode-guide/</span></span>
<span class="line"><span>├── docs/                      # 教程内容</span></span>
<span class="line"><span>│   ├── .vitepress/</span></span>
<span class="line"><span>│   │   └── config.ts         # VitePress 配置</span></span>
<span class="line"><span>│   ├── public/               # 静态资源</span></span>
<span class="line"><span>│   └── guide/                # 教程文章</span></span>
<span class="line"><span>│       ├── 1-getting-started/</span></span>
<span class="line"><span>│       ├── 2-basic-usage/</span></span>
<span class="line"><span>│       ├── 3-practical-workflows/</span></span>
<span class="line"><span>│       └── 4-next-steps/</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>├── CLAUDE.md                 # 项目规范（已有）</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><h2 id="open-questions" tabindex="-1">Open Questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open Questions&quot;">​</a></h2><ol><li>是否需要评论区/讨论区功能？</li><li>是否需要多语言版本（英文翻译）？</li><li>是否有具体的发布时间目标？</li></ol><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ol><li>一个完全没有接触过 Claude Code 的用户，能在 2-3 小时内完成入门篇</li><li>教程上线后有用户反馈&quot;对零基础友好&quot;</li><li>模块化结构能够轻松添加新内容</li></ol><h2 id="the-assignment" tabindex="-1">The Assignment <a class="header-anchor" href="#the-assignment" aria-label="Permalink to &quot;The Assignment&quot;">​</a></h2><p><strong>第一周行动：</strong> 搭建 VitePress 项目架子，完成&quot;入门篇&quot;的 4 篇文章初稿，在本地跑通 GitHub Pages 部署流程。</p><p>下一步可以选：</p><ul><li><code>/plan-eng-review</code> — 锁定技术方案和项目结构</li><li><code>/plan-design-review</code> — 设计网站视觉风格</li></ul>`,179)])])}const h=i(t,[["render",r]]);export{g as __pageData,h as default};
